(()=>{const r=e=>e.getBoundingClientRect();const vis=e=>{const b=r(e);const cs=getComputedStyle(e);return b.width>0&&b.height>0&&cs.visibility!=='hidden'&&!e.closest('.is-hidden')};
const hit=(a,b)=>a.left<b.right-0.5&&b.left<a.right-0.5&&a.top<b.bottom-0.5&&b.top<a.bottom-0.5;
const toasts=[...document.querySelectorAll('.toast')].filter(vis);
const stops=[...document.querySelectorAll('button')].filter(b=>vis(b)&&/^(Stop|Force stop)/.test((b.getAttribute('aria-label')||b.textContent).trim()));
const inputs=[...document.querySelectorAll('textarea, input:not([type=hidden]):not([type=checkbox]):not([type=radio]), [contenteditable=true]')].filter(vis);
const latest=[...document.querySelectorAll('.talk-jump')].filter(vis);
const issues=[];const sizes=[];
for(const s of stops){const b=r(s);const name=(s.getAttribute('aria-label')||s.textContent).trim().slice(0,32);sizes.push(Math.round(b.width)+'x'+Math.round(b.height));
 if(Math.min(b.width,b.height)<44)issues.push('small '+name+' '+Math.round(b.width)+'x'+Math.round(b.height));
 if(b.top<-0.5||b.left<-0.5||b.bottom>innerHeight+1||b.right>innerWidth+1)issues.push('offscreen '+name+' '+JSON.stringify([b.top,b.bottom,innerHeight]));
 const el=document.elementFromPoint((b.left+b.right)/2,(b.top+b.bottom)/2); if(!el||!s.contains(el))issues.push('covered '+name+' by '+(el?el.tagName+'.'+el.className:'none'));
 for(const t of toasts)if(hit(r(t),b))issues.push('toast over '+name);}
for(const i of inputs){for(const t of toasts)if(hit(r(t),r(i)))issues.push('toast over input '+(i.getAttribute('aria-label')||i.name||i.tagName));for(const l of latest)if(hit(r(l),r(i)))issues.push('latest over input');}
if(issues.length)throw new Error(issues.join('; '));return {vw:innerWidth,vh:innerHeight,stops:stops.length,sizes,toasts:toasts.length,inputs:inputs.length,latest:latest.length,issues}})()

